def fit_period(g, rmin=3,cmin=3):
    results=[]
    for p in range(2,13):
        maps={}
        counts={}
        for r in range(rmin,len(g)):
            for c in range(cmin,len(g[r])):
                v=g[r][c]
                if v==0: continue
                ph=(r+c)%p
                counts.setdefault(ph,{})[v]=counts.setdefault(ph,{}).get(v,0)+1
        mp={ph:max(d,key=d.get) for ph,d in counts.items()}
        correct=sum(mp.get((r+c)%p)==g[r][c] for r in range(rmin,len(g)) for c in range(cmin,len(g[r])) if g[r][c]!=0)
        n=sum(g[r][c]!=0 for r in range(rmin,len(g)) for c in range(cmin,len(g[r])))
        results.append((correct/n,p,correct,n,mp))
    return sorted(results,reverse=True)
