program='''def transform(grid):
    """Restore masked cells in the periodic interior and its frame."""
    h, w = len(grid), len(grid[0])
    interior = [(r, c, grid[r][c])
                for r in range(3, h) for c in range(3, w)
                if grid[r][c] != 0]

    best = None
    for period in range(2, 13):
        counts = {}
        for r, c, value in interior:
            phase = (r + c) % period
            counts.setdefault(phase, {})[value] = counts.setdefault(phase, {}).get(value, 0) + 1
        mapping = {phase: max(freq, key=freq.get) for phase, freq in counts.items()}
        correct = sum(mapping.get((r + c) % period) == value for r, c, value in interior)
        candidate = (correct, -period, mapping)
        if best is None or candidate[:2] > best[:2]:
            best = candidate

    period = -best[1]
    mapping = best[2]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = mapping[(r + c) % period]
    return out
